using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;using Demo6.Game;using Newtonsoft.Json;
public static class V056FxLive {public static object Start(){if(!Application.isPlaying||!Demo6.Game.PlayerController.Instance)throw new Exception("Original game required");if(UnityEngine.Object.FindAnyObjectByType<ImportedFxV056>())throw new Exception("Existing live FX pool preserved");new GameObject("V056 temporary live capture").AddComponent<V056FxLiveCapture>();return "Capturing ten consecutive real game frames for a synthetic wall-contact cue; no input injected";}}
public sealed class V056FxLiveCapture:MonoBehaviour {
 IEnumerator Start(){string dir="검증/v056-fx/live";Directory.CreateDirectory(dir);var before=UnityEngine.Random.state;var p=Demo6.Game.PlayerController.Instance;HitEffects.WallDust(p.Position+Vector2.right*1.1f,Vector2.right,6);var owner=UnityEngine.Object.FindAnyObjectByType<ImportedFxV056>();var trace=new List<object>();float started=Time.time;for(int i=0;i<10;i++){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(dir+"/frame-"+i.ToString("00")+".png",t.EncodeToPNG());Destroy(t);trace.Add(new{frame=Time.frameCount,time=Time.time-started,active=owner?owner.ActiveCount:0});}while(Time.time-started<.7f)yield return null;var result=new{method="Production hook + real unpaused engine frames; synthetic contact cue, no mouse/key injection",trace,activeAfterExpiry=owner?owner.ActiveCount:0,remainingParticles=owner?Array.ConvertAll(owner.GetComponentsInChildren<ParticleSystem>(true),x=>x.particleCount):new int[0]};File.WriteAllText(dir+"/runtime.json",JsonConvert.SerializeObject(result,Formatting.Indented));if(owner)Destroy(owner.gameObject);Destroy(gameObject);}
}
